// ref: https://github.com/stegu/webgl-noise/blob/master/src/noise3D.glsl

const snoise3D = `
	/*
		Description : Array and textureless GLSL 3D simplex 
		              noise functions.
		     Author : Ian McEwan, Ashima Arts.
		 Maintainer : stegu
		    Lastmod : 20201014 (stegu)
		    License : Copyright (C) 2011 Ashima Arts. All rights reserved.
		              Distributed under the MIT License. See LICENSE file.
		              https://github.com/ashima/webgl-noise
		              https://github.com/stegu/webgl-noise

		Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:
		The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.
		THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.
	*/

	vec3 mod289(vec3 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
	vec4 mod289(vec4 x) { return x - floor(x * (1.0 / 289.0)) * 289.0; }
	vec4 permute(vec4 x) { return mod289(((x*34.0)+10.0)*x); }
	vec4 taylorInvSqrt(vec4 r) { return 1.79284291400159 - 0.85373472095314 * r; }

	float snoise(vec3 v) { 
		const vec2  C = vec2(1.0/6.0, 1.0/3.0) ;
		const vec4  D = vec4(0.0, 0.5, 1.0, 2.0);

		vec3 i  = floor(v + dot(v, C.yyy) );
		vec3 x0 =   v - i + dot(i, C.xxx) ;

		vec3 g = step(x0.yzx, x0.xyz);
		vec3 l = 1.0 - g;
		vec3 i1 = min( g.xyz, l.zxy );
		vec3 i2 = max( g.xyz, l.zxy );

		vec3 x1 = x0 - i1 + C.xxx;
		vec3 x2 = x0 - i2 + C.yyy;
		vec3 x3 = x0 - D.yyy;

		i = mod289(i); 
		vec4 p = permute( permute( permute( 
							 i.z + vec4(0.0, i1.z, i2.z, 1.0 ))
						 + i.y + vec4(0.0, i1.y, i2.y, 1.0 )) 
						 + i.x + vec4(0.0, i1.x, i2.x, 1.0 ));

		float n_ = 0.142857142857;
		vec3  ns = n_ * D.wyz - D.xzx;

		vec4 j = p - 49.0 * floor(p * ns.z * ns.z);

		vec4 x_ = floor(j * ns.z);
		vec4 y_ = floor(j - 7.0 * x_ );

		vec4 x = x_ *ns.x + ns.yyyy;
		vec4 y = y_ *ns.x + ns.yyyy;
		vec4 h = 1.0 - abs(x) - abs(y);

		vec4 b0 = vec4( x.xy, y.xy );
		vec4 b1 = vec4( x.zw, y.zw );

		vec4 s0 = floor(b0)*2.0 + 1.0;
		vec4 s1 = floor(b1)*2.0 + 1.0;
		vec4 sh = -step(h, vec4(0.0));

		vec4 a0 = b0.xzyw + s0.xzyw*sh.xxyy ;
		vec4 a1 = b1.xzyw + s1.xzyw*sh.zzww ;

		vec3 p0 = vec3(a0.xy,h.x);
		vec3 p1 = vec3(a0.zw,h.y);
		vec3 p2 = vec3(a1.xy,h.z);
		vec3 p3 = vec3(a1.zw,h.w);

		vec4 norm = taylorInvSqrt(vec4(dot(p0,p0), dot(p1,p1), dot(p2, p2), dot(p3,p3)));
		p0 *= norm.x;
		p1 *= norm.y;
		p2 *= norm.z;
		p3 *= norm.w;

		vec4 m = max(0.5 - vec4(dot(x0,x0), dot(x1,x1), dot(x2,x2), dot(x3,x3)), 0.0);
		m = m * m;
		return 105.0 * dot( m*m, vec4( dot(p0,x0), dot(p1,x1), 
																	dot(p2,x2), dot(p3,x3) ) );
	}
`


// === Tab: gradient.js ===
// noprotect

const gradient = `
	// MIT License
	// Copyright © 2023 Zaron
	// Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:
	// The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.
	// THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.

	#define PI 3.141592653589793
	#define TWO_PI 6.283185307179586

	vec2 conical(vec2 uv, vec2 pos, float tile, float ofst) {
		uv -= pos;
		//uv.x *= iResolution.x/iResolution.y;  // square
		vec2 radialUv = vec2(atan(uv.y, uv.x)/TWO_PI+0.5, length(uv));
		radialUv = radialUv*tile-fract(ofst);
		return fract(radialUv);
	}

	float horizontal(vec2 uv, float tile, float ofst) {
		return fract( (uv*tile)-ofst ).x;
	}

	float radial(vec2 uv, vec2 pos, float tile, float ofst) {
		uv -= pos;
		//uv.x *= iResolution.x/iResolution.y;  // square
		float d = length(uv);
		d = d*tile-fract(ofst);
		return fract(d);
	}

	vec2 swirl(vec2 uv, vec2 pos, float tile, float ofst) {
		uv -= pos;
		//uv.x *= iResolution.x/iResolution.y;  // square
		vec2 radialUv = vec2(atan(uv.y, uv.x)/TWO_PI+0.5, length(uv));
		radialUv.x += radialUv.y*1.;
		radialUv = radialUv*tile-fract(ofst);
		return fract(radialUv);
	}

	float vertical(vec2 uv, float tile, float ofst) {
		return fract( (uv*tile)-ofst ).y;
	}
`


// === Tab: pixelate.js ===
// noprotect

const pixelate = `
	// MIT License
	// Copyright © 2023 Zaron
	// Permission is hereby granted, free of charge, to any person obtaining a copy of this software and associated documentation files (the "Software"), to deal in the Software without restriction, including without limitation the rights to use, copy, modify, merge, publish, distribute, sublicense, and/or sell copies of the Software, and to permit persons to whom the Software is furnished to do so, subject to the following conditions:
	// The above copyright notice and this permission notice shall be included in all copies or substantial portions of the Software.
	// THE SOFTWARE IS PROVIDED "AS IS", WITHOUT WARRANTY OF ANY KIND, EXPRESS OR IMPLIED, INCLUDING BUT NOT LIMITED TO THE WARRANTIES OF MERCHANTABILITY, FITNESS FOR A PARTICULAR PURPOSE AND NONINFRINGEMENT. IN NO EVENT SHALL THE AUTHORS OR COPYRIGHT HOLDERS BE LIABLE FOR ANY CLAIM, DAMAGES OR OTHER LIABILITY, WHETHER IN AN ACTION OF CONTRACT, TORT OR OTHERWISE, ARISING FROM, OUT OF OR IN CONNECTION WITH THE SOFTWARE OR THE USE OR OTHER DEALINGS IN THE SOFTWARE.

	/*
		Applies pixelation effect to the UV coordinates based on the pixel grid.

		Parameters:
			- uv: UV coordinates to be pixelated.
			- grid: Pixel grid. x => column, y => row

		Returns:
			Pixelated UV coordinates.
	*/
	vec2 pixelate(vec2 uv, vec2 grid) {
		uv *= grid;
		vec2 iuv = floor(uv)+.5;  // +.5 to center to cell
		return iuv/grid;
	}

	/*
		Applies pixelation effect to the UV coordinates based on the position of the origin point and the pixel grid.

		Parameters:
			- uv: UV coordinates to be pixelated.
			- pos: Position of the origin point.
			- grid: Pixel grid. x => column, y => row

		Returns:
			Pixelated UV coordinates.
	*/
	vec2 pixelate(vec2 uv, vec2 pos, vec2 grid) {
		uv -= pos;
		uv *= grid;
		vec2 iuv = floor(uv)+.5;  // +.5 to center to cell
		return iuv/grid;
	}

	/*
		Applies pixelation effect to the UV coordinates within a specified area based on the position, size, and pixel grid.
		Returns the original UV coordinates if they are outside the specified area.

		Parameters:
			- uv: UV coordinates to be pixelated.
			- pos: Start position of the pixelated area.
			- size: Size of the pixelated area. x => width, y => height
			- grid: Pixel grid. x => column, y => row

		Returns:
			Pixelated UV coordinates within the specified area or the original UV coordinates if outside the area.
	*/
	vec2 pixelate(vec2 uv, vec2 pos, vec2 size, vec2 grid) {
		if ( pos.x > uv.x || uv.x > pos.x+size.x ||
				 pos.y > uv.y || uv.y > pos.y+size.y ) {
				return uv;
		}
		uv -= pos;
		uv /= size;
		uv *= grid;
		vec2 iuv = floor(uv)+.5;  // +.5 to center to cell
		return iuv/grid*size+pos;
	}
`


// === Tab: shader.js ===
const vert = `#version 300 es

	in vec3 aPosition;
	in vec2 aTexCoord;

	out vec2 vTexCoord;

	void main() {
		vTexCoord = aTexCoord;
		gl_Position = vec4(aPosition.xy*2.-1., aPosition.z, 1.);
	}
`

const frag = `#version 300 es

	precision mediump float;

	uniform vec2 iResolution;
	uniform vec2 iMouse;
	uniform vec2 iGrid;
	uniform sampler2D iAtlas;
	uniform vec2 iAtlasGrid;
	uniform float iLength;
	uniform float iTime;
	uniform float iType;
	uniform bool iIsShadow;
	uniform bool iIsDistortions;
	uniform float iWei;

	in vec2 vTexCoord;
	out vec4 fragColor;

	${snoise3D}
	${gradient}
	${pixelate}

	float map(float value, float iMin, float iMax, float oMin, float oMax) {
		return (value-iMin)*(oMax-oMin)/(iMax-iMin)+oMin;
	}

	vec4 sprite(vec2 uv, sampler2D atlas, vec2 atlasGrid, float id) {
		uv /= atlasGrid;
		uv += vec2(mod(id, atlasGrid.x), floor(id / atlasGrid.x))/atlasGrid;
		return texture(atlas, uv);
	}

	vec2 lensDistortions(vec2 uv, vec2 mouse, float wei, float range, float exp) {
    float dist = pow(length(uv - mouse), exp);
    dist = smoothstep(0., range, dist);
    vec2 lensCenter = mouse + wei * dist * (uv - mouse);
    return uv + wei * (lensCenter - uv);
	}

	void main() {
		float t = iTime*.1;
		vec2 uv = vTexCoord;
		vec2 mo = iMouse/iResolution;
		uv.y = 1.-uv.y;
		uv -= 0.5;
		mo -= 0.5;
		mo.x *= iResolution.x/iResolution.y;
		uv.x *= iResolution.x/iResolution.y;

		if (iIsDistortions) {
			uv = lensDistortions(uv, mo, 1., 2., iWei);
		}

		vec2 fuv = fract(uv*iGrid);
		vec2 iuv = floor(uv*iGrid);
		vec2 puv = pixelate(uv, iGrid);

		float flow;
		if (iType == 1.)      flow = vertical(puv, 2., t);
		else if (iType == 2.) flow = horizontal(puv, 2., t);
		else if (iType == 3.) flow = radial(puv, vec2(0.), 2., t);
		else if (iType == 4.) flow = conical(puv, vec2(0.), 2., t).x;
		else if (iType == 5.) flow = swirl(puv, vec2(0.), 2., t).x;
		else if (iType == 6.) flow = .5+.5*snoise(vec3(puv, t));

		float id = floor(map(flow, 0., 1., 0., iLength-0.0001));
		vec4 sp = sprite(fuv, iAtlas, iAtlasGrid, id);

		fragColor = vec4(sp.rgb, 1.);
		if (iIsShadow) {
			fragColor *= (1.-length(uv-mo));
		}
	}
`

